-- Вопросы по триггерам: это вопросы ученика преподавателю, поэтому формулируются от первого лица ученика.
-- Меняются только тексты, которые никто не правил в админке (совпадают с прежними)
update triggers t set question_text = v.new_text
from (values
  ('ahead_plan', 'Какой вопрос по следующей теме хочется задать заранее?', 'Я продвинулся дальше плана недели. Что мне стоит изучить или подготовить заранее по следующей теме?'),
  ('booking_low', 'Откуда сейчас приходят новые клиенты и что можно усилить?', 'Моя запись заполнена меньше чем наполовину. Как привлечь новых клиентов и какой канал усилить в первую очередь?'),
  ('homework_overdue', 'Что остановило с домашкой: непонятно задание, не хватило времени или не видно смысла?', 'Я застрял с домашкой. С чего лучше начать и как понять, что она сделана правильно?'),
  ('insights_none', 'Что изменилось в понимании своей ситуации с прошлой записи?', 'Я давно не записывал выводы. Как их вести, чтобы они помогали мне расти?'),
  ('lessons_skipped', 'Что в этих уроках оказалось сложным или неинтересным?', 'Я пропустил пару уроков. Что в них самое важное и как мне быстрее догнать программу?'),
  ('metric_dropped', 'Что изменилось за период в записи, ценах или графике?', 'Одна из моих цифр просела за период. Как понять причину и что поменять в первую очередь?'),
  ('metric_flat', 'Какие действия за период должны были повлиять на эту цифру и какие из них не делались?', 'Эта цифра не изменилась за два замера. Какие действия мне усилить, чтобы она сдвинулась?'),
  ('no_actions_3d', 'Что мешает сделать хотя бы один маленький шаг на этой неделе?', 'Я несколько дней ничего не отмечал. Как вернуться в ритм и с какого шага начать?'),
  ('no_checkpoint', 'Какие цифры вызывают сомнение и поэтому замер откладывается?', 'Я не сдал замер вовремя. Как правильно посчитать цифры, в которых я сомневаюсь?'),
  ('notes_none', 'Что важного из созвона хочется не потерять?', 'После созвона у меня нет конспекта. Что из разбора самое важное и что применить в первую очередь?'),
  ('perspective_gap', 'Что из пройденного уже можно применить к клиентам на этой неделе?', 'Я прошёл много материала, а цифры выросли пока мало. Что применить к клиентам уже на этой неделе?'),
  ('price_flat', 'Что мешает поднять цену прямо сейчас?', 'Мой средний чек не растёт уже несколько недель. Как понять, что пора поднимать цену, и на сколько?'),
  ('stuck_lesson', 'На каком месте урока остановился и что осталось непонятным?', 'Я застрял на уроке. Какие моменты в нём самые важные и как применить их на практике?'),
  ('video_views_low', 'Что менялось между роликами и что кажется слабым местом?', 'Просмотры моих видео не растут. Что поменять в роликах: формат, хуки или публикацию?'),
  ('video_zero_direction', 'Что мешает снять видео этого направления?', 'Я давно не снимал видео этого направления. Какой формат взять для старта?')
) v(code, old_text, new_text)
where t.code = v.code and t.question_text = v.old_text;
